var xVariantParseErrorPrintContext func(*Error, string) string

func VariantParseErrorPrintContext(ErrorVar *Error, SourceStrVar string) string {
	cret := xVariantParseErrorPrintContext(ErrorVar, SourceStrVar)
	return cret
}

